export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = Object.entries(thresholds).map(([metricId, minScore]) => {
    const evaluation = evaluations.find(e => e.id === metricId);
    const score = evaluation?.score;
    return {
      metric: metricId,
      min: minScore,
      score: score,
      passed: score !== null && score !== undefined && score >= minScore
    };
  });

  const allThresholdsPassed = thresholdResults.length === 0 || thresholdResults.every(t => t.passed);

  return {
    passed: allThresholdsPassed,
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    thresholds: thresholdResults
  };
}

