1	export function parseThresholds(thresholdStrings = [], validMetricIds = []) {
2	  if (!thresholdStrings || thresholdStrings.length === 0) {
3	    return {};
4	  }
5	
6	  const result = {};
7	  const validIds = new Set(validMetricIds);
8	
9	  for (const thresholdString of thresholdStrings) {
10	    const match = thresholdString.match(/^([a-z_]+)=(-?[0-9.]+)$/);
11	    if (!match) {
12	      throw new Error(
13	        `Invalid threshold format: "${thresholdString}". Expected: metric=number (e.g., exact_match=0.9)`
14	      );
15	    }
16	
17	    const [, metricId, valueStr] = match;
18	    const value = parseFloat(valueStr);
19	
20	    if (Number.isNaN(value) || value < 0 || value > 1) {
21	      throw new Error(
22	        `Invalid threshold value "${value}" for "${metricId}". Must be a number between 0 and 1.`
23	      );
24	    }
25	
26	    if (!validIds.has(metricId)) {
27	      throw new Error(
28	        `Unknown metric: "${metricId}". Valid metrics: ${Array.from(validIds).join(', ')}`
29	      );
30	    }
31	
32	    result[metricId] = value;
33	  }
34	
35	  return result;
36	}
