62	export function generateReport({
63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString(),
67	  thresholds = {}
68	} = {}) {
69	  const totalSamples = evaluations.reduce((total, metric) => {
70	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
71	    return total;
72	  }, 0);
73	
74	  const thresholdResults = Object.entries(thresholds).map(([metricId, minScore]) => {
75	    const evaluation = evaluations.find(e => e.id === metricId);
76	    const score = evaluation?.score;
77	    return {
78	      metric: metricId,
79	      min: minScore,
80	      score: score,
81	      passed: score !== null && score !== undefined && score >= minScore
82	    };
83	  });
84	
85	  const allThresholdsPassed = thresholdResults.length === 0 || thresholdResults.every(t => t.passed);
86	
87	  return {
88	    passed: allThresholdsPassed,
89	    metadata: {
90	      generatedAt,
91	      outputsPath,
92	      referencesPath,
93	      totalSamples
94	    },
95	    metrics: evaluations,
96	    thresholds: thresholdResults
97	  };
98	}
