52	export function resolveReportPath(reportPath, format = 'json') {
53	  if (!reportPath) {
54	    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
55	  }
56	  const ext = path.extname(reportPath);
57	  if (!ext) {
58	    return format === 'markdown' ? `${reportPath}.md` : `${reportPath}.json`;
59	  }
60	  return reportPath;
61	}
